WITH RECURSIVE
rev AS (SELECT * FROM atlas.decision_revisions WHERE revision = %(revision)s),
ent AS (SELECT e.* FROM atlas.entity_registry_revisions e JOIN rev d ON e.revision=d.entity_revision),
source_refs(source_id, version) AS (
 SELECT source_id, source_version FROM atlas.decision_features WHERE revision = %(revision)s
 UNION
 SELECT source_id, source_version FROM atlas.decision_mainland_boundary_sources WHERE revision = %(revision)s
 UNION
 SELECT source_id, source_version FROM atlas.decision_stage1_source_inputs WHERE revision = %(revision)s
 UNION
 SELECT source_id, source_version FROM atlas.decision_mainland_closure_sources WHERE revision = %(revision)s
 UNION
 SELECT dep.parent_source_id, dep.parent_version FROM atlas.source_asset_dependencies dep
 JOIN source_refs r ON (dep.source_id,dep.version)=(r.source_id,r.version)
)
SELECT jsonb_build_object(
 'schema','worldatlas-geography-decision-draft-evidence-v1',
 'serialization','worldatlas-canonical-json-v1', 'source','neon-export',
 'decision_revision',(SELECT jsonb_build_object('id',revision,'entity_revision',entity_revision,'status',status,'evidence',evidence,'reviewed_by',reviewed_by,'reviewed_at',reviewed_at) FROM rev),
 'entity_revision',(SELECT jsonb_build_object('id',revision,'status',status,'reviewed_by',reviewed_by,'reviewed_at',reviewed_at) FROM ent),
 'sources',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.source_id,s.version) FROM (SELECT a.source_id,a.version,a.sha256,a.size_bytes,a.r2_bucket,a.r2_key FROM atlas.source_assets a WHERE EXISTS (SELECT 1 FROM atlas.decision_features f WHERE f.revision=%(revision)s AND (f.source_id,f.source_version)=(a.source_id,a.version)) OR EXISTS (SELECT 1 FROM atlas.decision_mainland_boundary_sources r WHERE r.revision=%(revision)s AND (r.source_id,r.source_version)=(a.source_id,a.version)) OR EXISTS (SELECT 1 FROM atlas.decision_stage1_source_inputs s1 WHERE s1.revision=%(revision)s AND (s1.source_id,s1.source_version)=(a.source_id,a.version)) OR EXISTS (SELECT 1 FROM atlas.decision_mainland_closure_sources rs WHERE rs.revision=%(revision)s AND (rs.source_id,rs.source_version)=(a.source_id,a.version))) s),'[]'::jsonb),
 'source_lineage_assets',COALESCE((SELECT jsonb_agg(to_jsonb(a) - 'created_at' ORDER BY a.source_id,a.version) FROM atlas.source_assets a JOIN source_refs r USING (source_id,version)),'[]'::jsonb),
 'source_lineage_dependencies',COALESCE((SELECT jsonb_agg(to_jsonb(dep) ORDER BY dep.source_id,dep.version,dep.parent_source_id,dep.parent_version) FROM atlas.source_asset_dependencies dep JOIN source_refs r ON (dep.source_id,dep.version)=(r.source_id,r.version)),'[]'::jsonb),
 'entities',COALESCE((SELECT jsonb_agg(to_jsonb(g)-'revision' ORDER BY g.id) FROM atlas.geographic_entities g JOIN ent e USING (revision)),'[]'::jsonb),
 'category_bindings',COALESCE((SELECT jsonb_agg(to_jsonb(b)-'revision' ORDER BY b.code) FROM atlas.review_category_bindings b JOIN ent e USING (revision)),'[]'::jsonb),
 'features',COALESCE((SELECT jsonb_agg(to_jsonb(f)-'revision' ORDER BY f.feature_id) FROM atlas.decision_features f JOIN rev d USING (revision)),'[]'::jsonb),
 'endpoints',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'revision' ORDER BY p.endpoint_id) FROM atlas.decision_endpoints p JOIN rev d USING (revision)),'[]'::jsonb),
 'routes',COALESCE((SELECT jsonb_agg(t.obj ORDER BY t.id) FROM (
 SELECT r.route_id id,(to_jsonb(r)-'revision')||jsonb_build_object('points',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'revision'-'route_id' ORDER BY p.ordinal) FROM atlas.decision_route_points p WHERE p.revision=r.revision AND p.route_id=r.route_id),'[]'::jsonb)) obj FROM atlas.decision_routes r JOIN rev d USING(revision)
 UNION ALL
 SELECT c.route_id id,(to_jsonb(c)-'revision'-'start_boundary_id'-'start_endpoint'-'end_boundary_id'-'end_endpoint'-'provenance') || jsonb_build_object('decision_revision',c.revision,'start_terminal',jsonb_build_object('boundary_id',c.start_boundary_id,'endpoint',c.start_endpoint),'end_terminal',jsonb_build_object('boundary_id',c.end_boundary_id,'endpoint',c.end_endpoint),'provenance',c.provenance||jsonb_build_object('source_refs',COALESCE((SELECT jsonb_agg(jsonb_build_object('source_id',x.source_id,'version',x.source_version) ORDER BY x.source_id,x.source_version) FROM atlas.decision_mainland_closure_sources x WHERE (x.revision,x.route_id)=(c.revision,c.route_id)),'[]'::jsonb)),'points','[]'::jsonb) obj FROM atlas.decision_mainland_closure_routes c WHERE c.revision=%(revision)s
 ) t),'[]'::jsonb),
 'basins',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',b.basin_id,'feature_id',b.feature_id,'source_id',f.source_id,'source_version',f.source_version,'source_feature_id',f.source_feature_id,'geometry_sha256',f.geometry_sha256,'assignment_method',b.method,'tie_rules',b.tie_rules,'evidence',b.evidence,'participant_entity_ids',COALESCE((SELECT jsonb_agg(p.entity_id ORDER BY p.entity_id) FROM atlas.decision_basin_participants p WHERE p.revision=b.revision AND p.basin_id=b.basin_id),'[]'::jsonb)) ORDER BY b.basin_id) FROM atlas.decision_basins b JOIN rev d USING (revision) LEFT JOIN atlas.decision_features f ON (f.revision,f.feature_id)=(b.revision,b.feature_id)),'[]'::jsonb),
 'affiliations',COALESCE((SELECT jsonb_agg(to_jsonb(a)-'revision'-'entity_revision' ORDER BY a.affiliation_id) FROM atlas.decision_affiliations a JOIN rev d USING (revision)),'[]'::jsonb),
 'land_component_witness_rules',COALESCE((SELECT jsonb_agg(to_jsonb(w)-'revision'-'entity_revision' ORDER BY w.rule_id) FROM atlas.decision_land_component_witness_rules w JOIN rev d USING (revision)),'[]'::jsonb),
 'ocean_seeds',COALESCE((SELECT jsonb_agg(to_jsonb(s)-'revision'-'entity_revision' ORDER BY s.seed_id) FROM atlas.decision_ocean_seeds s JOIN rev d USING (revision)),'[]'::jsonb),
 'policies',COALESCE((SELECT jsonb_agg(p.obj ORDER BY p.id) FROM (SELECT policy_id id, jsonb_build_object('id',policy_id,'kind',kind,'definition',definition,'evidence',evidence) obj FROM atlas.decision_policies WHERE revision=%(revision)s UNION ALL SELECT policy_id id,jsonb_build_object('id',policy_id,'kind','ocean_fill','definition',definition,'evidence',evidence) obj FROM atlas.decision_ocean_fill_policies WHERE revision=%(revision)s UNION ALL SELECT policy_id id,jsonb_build_object('id',policy_id,'kind',kind,'definition',definition,'evidence',evidence) obj FROM atlas.decision_water_assignment_policies WHERE revision=%(revision)s) p),'[]'::jsonb) ,
 'mainland_boundaries',COALESCE((SELECT jsonb_agg((to_jsonb(b)-'revision'-'provenance') || jsonb_build_object('decision_revision',b.revision,'provenance',b.provenance || jsonb_build_object('source_refs',COALESCE((SELECT jsonb_agg(jsonb_build_object('source_id',x.source_id,'version',x.source_version) ORDER BY x.source_id,x.source_version) FROM atlas.decision_mainland_boundary_sources x WHERE (x.revision,x.boundary_id)=(b.revision,b.boundary_id)),'[]'::jsonb))) ORDER BY b.boundary_id) FROM atlas.decision_mainland_boundaries b WHERE b.revision=%(revision)s),'[]'::jsonb),
 'distance_policies',COALESCE((SELECT jsonb_agg(to_jsonb(d)||jsonb_build_object('decision_revision',s.revision,'execution_status',s.execution_status) ORDER BY d.policy_id,d.version) FROM atlas.decision_distance_policy_selections s JOIN atlas.distance_policy_versions d USING(policy_id,version) WHERE s.revision=%(revision)s),'[]'::jsonb),
 'stage1_source_inputs',COALESCE((SELECT jsonb_agg((to_jsonb(s)-'revision')||jsonb_build_object('decision_revision',s.revision) ORDER BY s.role,s.ordinal) FROM atlas.decision_stage1_source_inputs s WHERE s.revision=%(revision)s),'[]'::jsonb),
 'land_baseline_policy',(SELECT (to_jsonb(p)-'revision')||jsonb_build_object('decision_revision',p.revision,'boundary_ids',COALESCE((SELECT jsonb_agg(x.boundary_id ORDER BY x.boundary_id) FROM atlas.decision_land_baseline_boundaries x WHERE x.revision=p.revision),'[]'::jsonb),'route_ids',COALESCE((SELECT jsonb_agg(x.route_id ORDER BY x.route_id) FROM atlas.decision_land_baseline_routes x WHERE x.revision=p.revision),'[]'::jsonb),'region_ids',COALESCE((SELECT jsonb_agg(x.region_id ORDER BY x.region_id) FROM atlas.decision_land_baseline_regions x WHERE x.revision=p.revision),'[]'::jsonb),'mainland_rule_ids',COALESCE((SELECT jsonb_agg(x.rule_id ORDER BY x.rule_id) FROM atlas.decision_land_baseline_rules x WHERE x.revision=p.revision),'[]'::jsonb)) FROM atlas.decision_land_baseline_policies p WHERE p.revision=%(revision)s),
 'seed_regions',COALESCE((SELECT jsonb_agg(jsonb_build_object('region_id',r.region_id,'decision_revision',r.revision,'execution_status',r.execution_status,'geometry_sha256',r.geometry_sha256,'geometry_hash_method',r.geometry_hash_method,'witnesses',r.witnesses,'segments',COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',s.kind,'id',COALESCE(s.boundary_id,s.route_id),'start',s.start_index,'end',s.end_index,'reverse',s.reverse) ORDER BY s.ordinal) FROM atlas.decision_mainland_region_segments s WHERE (s.revision,s.region_id)=(r.revision,r.region_id)),'[]'::jsonb)) ORDER BY r.region_id) FROM atlas.decision_mainland_seed_regions r WHERE r.revision=%(revision)s),'[]'::jsonb),
 'mainland_component_rules',COALESCE((SELECT jsonb_agg((to_jsonb(r)-'revision'-'entity_revision')||jsonb_build_object('decision_revision',r.revision) ORDER BY r.rule_id) FROM atlas.decision_mainland_component_rules r WHERE r.revision=%(revision)s),'[]'::jsonb),
 'mainland_witnesses',COALESCE((SELECT jsonb_agg((to_jsonb(w)-'revision')||jsonb_build_object('decision_revision',w.revision) ORDER BY w.witness_id) FROM atlas.decision_mainland_witnesses w WHERE w.revision=%(revision)s),'[]'::jsonb),
 'mainland_witness_groups',COALESCE((SELECT jsonb_agg((to_jsonb(g)-'revision')||jsonb_build_object('decision_revision',g.revision,'witness_ids',COALESCE((SELECT jsonb_agg(m.witness_id ORDER BY m.ordinal) FROM atlas.decision_mainland_witness_group_members m WHERE (m.revision,m.group_id)=(g.revision,g.group_id)),'[]'::jsonb),'target_entity_ids',COALESCE((SELECT jsonb_agg(t.entity_id ORDER BY t.entity_id) FROM atlas.decision_mainland_witness_group_targets t WHERE (t.revision,t.group_id)=(g.revision,g.group_id)),'[]'::jsonb)) ORDER BY g.group_id) FROM atlas.decision_mainland_witness_groups g WHERE g.revision=%(revision)s),'[]'::jsonb),
 'mainland_group_relations',COALESCE((SELECT jsonb_agg((to_jsonb(r)-'revision'-'group_a'-'group_b')||jsonb_build_object('decision_revision',r.revision,'group_ids',jsonb_build_array(r.group_a,r.group_b)) ORDER BY r.relation_id) FROM atlas.decision_mainland_group_relations r WHERE r.revision=%(revision)s),'[]'::jsonb)

)::text AS snapshot;
